        self.assertEqual(run(['3', '1', '2']), {'n': 3, 'total': 51, 'label': 'ALPHA'})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 3, 'total': 123, 'label': 'ALPHA'})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 3, 'total': 69, 'label': 'ALPHA'})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 0, 'total': 0, 'label': 'EMPTY'})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'total': 195, 'label': 'ALPHA'})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'total': 4, 'label': 'ALPHA'})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'total': 196, 'label': 'ALPHA'})
    def test_case_07(self):
        self.assertEqual(run(['2', 'hello', '40']), {'n': 2, 'total': 140, 'label': 'ALPHA'})

